## Verifying the signature - PHP

``` php
function verifyPayscribeWebhook(string $secret): bool
{
    $eventId   = $_SERVER['HTTP_X_PAYSCRIBE_EVENT_ID']  ?? '';
    $timestamp = $_SERVER['HTTP_X_PAYSCRIBE_TIMESTAMP'] ?? '';
    $sigHeader = $_SERVER[&#x27;HTTP_X_PAYSCRIBE_SIGNATURE&#x27;] ?? &#x27;&#x27;;   // "v1=<hex>"
    $rawBody   = file_get_contents('php://input');
    // 1. Validate signature header format
    if (!preg_match('/^v1=([0-9a-f]{64})$/', $sigHeader, $m)) {
        http_response_code(400);
        exit('Invalid signature header');
    }
    $givenSig = $m[1];
    // 2. Reject stale timestamps (replay protection)
    if (abs(time() - (int)$timestamp) > 300) {
        http_response_code(401);
        exit('Stale webhook — timestamp too old');
    }
    // 3. Recompute HMAC
    $base = $timestamp . '.' . $eventId . '.' . $rawBody;
    $calc = hash_hmac('sha256', $base, $secret);
    // 4. Constant-time comparison
    if (!hash_equals($calc, $givenSig)) {
        http_response_code(401);
        exit('Signature mismatch');
    }
    return true;
}
// Usage
$secret = 'sk_live_your_secret_key';
verifyPayscribeWebhook($secret);
$event = json_decode(file_get_contents('php://input'), true);
// Idempotency - skip if already processed
$eventId = $event['event_id'];
// if (alreadyProcessed($eventId)) { http_response_code(200); exit('duplicate'); }
switch ($event['event_type']) {
    case 'bills.created':
        // handle ...
        break;
    case 'cards.*':
        // handle ...
        break;
    case 'invoice.paid':
        // handle ...
        break;
    case 'payment_link.paid':
        // handle ...
        break;
    case 'savings.contribution.success':
        // handle ...
        break;
}
http_response_code(200);
echo 'OK';

 ```

## Verifying the signature — Node.js

``` js
const crypto = require('crypto');
function verifyPayscribeWebhook(req, secret) {
  const eventId   = req.headers['x-payscribe-event-id']  ?? '';
  const timestamp = req.headers['x-payscribe-timestamp'] ?? '';
  const sigHeader = req.headers[&#x27;x-payscribe-signature&#x27;] ?? &#x27;&#x27;; // "v1=<hex>"
  // rawBody must be the raw Buffer/string - not req.body (already parsed)
  const rawBody = req.rawBody; // set via express.raw() or similar
  // 1. Validate header format
  const match = sigHeader.match(/^v1=([0-9a-f]{64})$/);
  if (!match) return false;
  const givenSig = match[1];
  // 2. Replay protection
  if (Math.abs(Date.now() / 1000 - Number(timestamp)) > 300) return false;
  // 3. Recompute HMAC
  const base = `${timestamp}.${eventId}.${rawBody}`;
  const calc = crypto.createHmac('sha256', secret).update(base).digest('hex');
  // 4. Constant-time comparison
  return crypto.timingSafeEqual(Buffer.from(calc), Buffer.from(givenSig));
}
// Express example
app.post('/webhooks/payscribe',
  express.raw({ type: 'application/json' }),
  (req, res) => {
    req.rawBody = req.body.toString('utf8');
    if (!verifyPayscribeWebhook(req, process.env.PAYSCRIBE_SECRET)) {
      return res.status(401).send('Signature verification failed');
    }
    const event = JSON.parse(req.rawBody);
    switch (event.event_type) {
      case 'bills.*':                /* handle */ break;
      case 'cards.*':                /* handle */ break;
      case 'invoice.paid':           /* handle */ break;
      case 'payment_link.paid':      /* handle */ break;
      case 'savings.withdrawal.success': /* handle */ break;
    }
    res.status(200).send('OK');
  }
);

 ```

