  "type": "object",
  "properties": {
    "status": {
      "type": "boolean"
    },
    "description": {
      "type": "string"
    },
    "message": {
      "type": "object",
      "properties": {
        "details": {
          "type": "array",
          "items": {
            "type": "object",
            "properties": {
              "id": {
                "type": "string"
              },
              "title": {
                "type": "string"
              }
            }
          }
        }
      }
    },
    "status_code": {
      "type": "integer"
    }
  }
}

