                "first_six": {"type": "string"},
                "last_four": {"type": "string"},
                "masked": {"type": "string"},
                "number": {"type": "string"},
                "expiry": {"type": "string"},
                "ccv": {"type": "string"},
                "billing": {
                  "type": "object",
                  "properties": {
                    "address": {"type": "string"},
                    "state": {"type": "string"},
                    "city": {"type": "string"},
                    "postal_code": {"type": "string"},
                    "country": {"type": "string"}
                  }
                },
                "created_at": {"type": "string"},
                "updated_at": {"type": "string"}
              }
            },
            "customer": {
              "type": "object",
              "properties": {
                "id": {"type": "string"},
                "name": {"type": "string"}
              }
            },
            "status_code": {"type": "integer"}
